steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(name: \"Web\") {
        nodes {
          id
          name
          workflowStates(kinds: [completed]) {
            nodes {
              id
              name
            }
          }
        }
      }
      users(name: \"Priya Nair\") {
        nodes {
          id
          name
        }
      }
    }
  }'
